import * as THREE from 'three';
import {GLTFLoader} from '../vendor/GLTFLoader.js';
import {clone} from '../vendor/SkeletonUtils.js';
import {LocalActor,defaults,OPTIONS,sanitize,walkable} from './controller.js';
export async function createPrototype(host){
 const renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.5));renderer.setClearColor(0,0);renderer.outputColorSpace=THREE.SRGBColorSpace;
 const scene=new THREE.Scene(),camera=new THREE.OrthographicCamera(),actors=[],models=[],mixers=[],actions=[],labels=[],depthMeshes=[];let positioned=false;let snapshot=null,last=0,size='',selected=0,disposed=false;
 const depthMaterial=new THREE.MeshBasicMaterial({colorWrite:false}),boxGeo=new THREE.BoxGeometry(1,1,1);
 scene.add(new THREE.HemisphereLight(0xd5efff,0x5e534d,2.4));const light=new THREE.DirectionalLight(0xffefda,3.2);light.position.set(-3,8,5);scene.add(light);
 let asset;try{asset=await new GLTFLoader().loadAsync(new URL('./assets/keyhq-original.glb',import.meta.url).href)}catch(e){renderer.dispose();throw e}
 renderer.domElement.className='avatar-webgl';renderer.domElement.setAttribute('aria-hidden','true');host.stage.append(renderer.domElement);
 const status=document.createElement('div');status.className='prototype-controls';status.innerHTML='<strong>PHASE 1 · LOCAL PROTOTYPE</strong><div><select aria-label="Selected prototype avatar"></select><button data-act="custom">Customize</button><button data-act="focus">Close-up</button></div><div class="prototype-actions">'+[['idle','Stand'],['walk','Move'],['sit','Sit'],['work','Work'],['talk','Talk'],['wave','Wave'],['auto','Auto']].map(([k,v])=>`<button data-act="${k}">${v}</button>`).join('')+'</div><small role="status">Select an avatar, then Move and click a clear floor area.</small>';host.stage.append(status);
 const selector=status.querySelector('select'),note=status.querySelector('small');
 const key='keyhq:phase1:avatar:v1';let profiles=defaults.map((d,i)=>{try{return sanitize(JSON.parse(localStorage.getItem(key+':'+i)),i)}catch(_){return {...d}}});
 function updateNames(){selector.replaceChildren(...profiles.map((p,i)=>{const o=document.createElement('option');o.value=i;o.textContent=p.name;return o}));selector.value=selected}
 for(let i=0;i<2;i++){const model=clone(asset.scene);model.scale.setScalar(.52);model.traverse(o=>{if(o.isMesh){o.material=o.material.clone();o.renderOrder=1}});scene.add(model);models.push(model);const mixer=new THREE.AnimationMixer(model);mixers.push(mixer);actions.push(Object.fromEntries(asset.animations.map(c=>[c.name,mixer.clipAction(c)])));actors.push(new LocalActor(i));const label=document.createElement('button');label.className='prototype-name';label.onclick=()=>{selected=i;selector.value=i;refresh()};host.stage.append(label);labels.push(label)}
 function apply(i){const p=profiles[i],model=models[i];model.traverse(o=>{if(!o.isMesh)return;if(o.name.startsWith('hair_'))o.visible=o.name==='hair_'+p.hair;if(o.name==='business')o.visible=p.outfit==='business';if(o.name==='uniform')o.visible=p.outfit==='keylargo';if(o.name==='glasses')o.visible=p.accessory==='glasses';const n=o.material.name;if(n==='skin')o.material.color.set(p.skin);if(n==='hair')o.material.color.set(p.hairColor);if(n==='shirt')o.material.color.set(p.outfit==='business'?'#305577':p.outfit==='casual'?'#b94e65':'#173c68');if(n==='shoes')o.material.color.set({black:'#172130',brown:'#78503c',white:'#e8e7df'}[p.shoes])});const width=p.body==='slim'?.9:p.body==='broad'?1.14:1;model.scale.set(.52*width*(p.gender==='female'?.95:1),.52,.52);const head=model.getObjectByName('Head');head.scale.set(p.face==='round'?1.1:p.face==='defined'?.94:1,p.face==='round'?.94:1,1);labels[i].textContent=p.name}
 function refresh(){status.querySelectorAll('[data-act]').forEach(b=>b.classList.toggle('active',b.dataset.act===actors[selected].state||(b.dataset.act==='auto'&&actors[selected].auto)));labels.forEach((l,i)=>l.classList.toggle('selected',i===selected));note.textContent=actors[selected].auto?'Automatic behaviour · local demonstration only.':'Manual control · Auto resumes automatic behaviour.'}
 selector.onchange=()=>{selected=Number(selector.value);refresh()};let moveMode=false;
 function command(action){const actor=actors[selected];if(action==='custom')return customize();if(action==='focus')return host.focus();if(action==='auto'){actor.auto=true;actor.nextDecision=0;moveMode=false;refresh();return}if(action==='walk'){actor.command('idle');moveMode=true;refresh();note.textContent='Click an open floor area. Furniture and room boundaries are blocked.';return}moveMode=false;const seat=snapshot?.desks[selected];const ok=(action==='sit'||action==='work')?seat&&actor.command(action,{target:{x:seat.x,y:seat.y-seat.facing*.43},seat,desks:snapshot.desks}):actor.command(action);refresh();if(!ok)note.textContent='No clear route to this chair. Choose another location.'}
 status.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>command(b.dataset.act));
 function pointer(event){if(!moveMode||!snapshot||Number(snapshot.floor)!==5||event.button!==0)return;const r=host.canvas.getBoundingClientRect(),sx=(event.clientX-r.left-snapshot.W/2-snapshot.camera.x)/snapshot.scale,sy=(event.clientY-r.top-snapshot.H/2-snapshot.camera.y+(snapshot.z-snapshot.camera.z)*Math.cos(snapshot.camera.tilt)*snapshot.scale)/snapshot.scale/Math.sin(snapshot.camera.tilt),a=snapshot.camera.angle;const target={x:sx*Math.cos(a)+sy*Math.sin(a),y:-sx*Math.sin(a)+sy*Math.cos(a)};const other=actors[1-selected];if(Math.hypot(target.x-other.x,target.y-other.y)<.3){note.textContent='Choose a spot away from the other avatar.';return}if(actors[selected].command('idle',{target,desks:snapshot.desks})){moveMode=false;refresh();event.stopImmediatePropagation();event.preventDefault()}else note.textContent='That spot is occupied or outside the walkable office.'}
 host.canvas.addEventListener('pointerdown',pointer,true);
 const dialog=document.createElement('dialog');dialog.className='prototype-editor';dialog.innerHTML='<form method="dialog"><header><h2>Customize local avatar</h2><button value="cancel" aria-label="Close">×</button></header><p>Saved on this browser only. Employee accounts are unchanged.</p><div class="prototype-fields"></div><p class="save-message" role="status"></p><footer><button value="cancel">Cancel</button><button type="button" data-save>Save avatar</button></footer></form>';document.body.append(dialog);
 function customize(){const p=profiles[selected],fields=dialog.querySelector('.prototype-fields');fields.replaceChildren();for(const key of ['name',...Object.keys(OPTIONS),'skin','hairColor']){const label=document.createElement('label');label.textContent=({hairColor:'Hair color',skin:'Skin tone',body:'Body preset',face:'Face preset',outfit:'Clothing'}[key]||key);const input=OPTIONS[key]?document.createElement('select'):document.createElement('input');if(OPTIONS[key])OPTIONS[key].forEach(value=>{const opt=document.createElement('option');opt.value=value;opt.textContent=value;input.append(opt)});else input.type=key==='name'?'text':'color';input.name=key;input.value=p[key];if(key==='name')input.maxLength=32;label.append(input);fields.append(label)}dialog.querySelector('.save-message').textContent='';dialog.showModal()}
 dialog.querySelector('[data-save]').onclick=()=>{const values=Object.fromEntries(new FormData(dialog.querySelector('form')));profiles[selected]=sanitize(values,selected);apply(selected);updateNames();try{localStorage.setItem(key+':'+selected,JSON.stringify(profiles[selected]));dialog.close();host.toast('Local avatar saved.')}catch(_){dialog.querySelector('.save-message').textContent='Applied for this session. Browser storage is unavailable.'}};
 profiles.forEach((_,i)=>apply(i));updateNames();refresh();
 renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();dispose();host.onFatal?.();host.toast('3D context lost. Use Retry 3D prototype to restart.')});
 function frame(s){if(disposed)return;snapshot=s;if(!positioned){actors.forEach((actor,i)=>{if(!walkable(actor.x,actor.y,s.desks)){const choices=[];for(let x=-3.8;x<=3.8;x+=.2)for(let y=-2;y<=.6;y+=.2)if(walkable(x,y,s.desks)&&actors.every((other,j)=>j===i||Math.hypot(x-other.x,y-other.y)>.3))choices.push({x,y,d:Math.hypot(x-actor.x,y-actor.y)});choices.sort((a,b)=>a.d-b.d);if(choices[0])Object.assign(actor,{x:choices[0].x,y:choices[0].y})}});positioned=true}const visible=Number(s.floor)===5;renderer.domElement.hidden=!visible;status.hidden=!visible;labels.forEach(l=>l.hidden=!visible);if(!visible){last=0;return}const dt=last?Math.min((s.now-last)/1000,.05):0;last=s.now;if(size!==`${s.W},${s.H}`){size=`${s.W},${s.H}`;renderer.setSize(s.W,s.H)}const c=s.camera,ca=Math.cos(c.angle),sa=Math.sin(c.angle),st=Math.sin(c.tilt),ct=Math.cos(c.tilt);camera.left=(-s.W/2-c.x)/s.scale;camera.right=(s.W/2-c.x)/s.scale;camera.top=(s.H/2+c.y)/s.scale;camera.bottom=(-s.H/2+c.y)/s.scale;camera.near=.01;camera.far=100;camera.position.set(sa*ct*30,c.z+st*30,ca*ct*30);camera.up.set(-sa*st,ct,-ca*st);camera.lookAt(0,c.z,0);camera.updateProjectionMatrix();
 // Depth-only copies use the exact existing furniture boxes, avoiding a second layout.
 s.geometry.forEach((g,i)=>{let mesh=depthMeshes[i];if(!mesh){mesh=new THREE.Mesh(boxGeo,depthMaterial);scene.add(mesh);depthMeshes.push(mesh)}mesh.visible=true;mesh.position.set(g[0]+g[3]/2,g[2]+g[5]/2,g[1]+g[4]/2);mesh.scale.set(g[3],g[5],g[4])});for(let i=s.geometry.length;i<depthMeshes.length;i++)depthMeshes[i].visible=false;
 actors.forEach((actor,i)=>{const old=actor.state;actor.update(dt,s.now,s.desks);const state=actor.state;labels[i].dataset.state=state;if(models[i].userData.clip!==state){const prev=actions[i][models[i].userData.clip];actions[i][state].reset().fadeIn(.22).play();prev?.fadeOut(.22);models[i].userData.clip=state;if(i===selected)refresh()}mixers[i].update(dt);models[i].position.set(actor.x,s.z,actor.y);models[i].rotation.y=actor.facing;const pt=host.project(actor.x,actor.y,s.z+(state==='sit'||state==='work'?.92:1.07));labels[i].style.left=pt.x+'px';labels[i].style.top=(pt.y-10)+'px';host.reserveLabel?.({x:pt.x,y:pt.y-21,w:labels[i].offsetWidth})});renderer.render(scene,camera)}
 function dispose(){if(disposed)return;disposed=true;host.canvas.removeEventListener('pointerdown',pointer,true);mixers.forEach((m,i)=>{m.stopAllAction();m.uncacheRoot(models[i])});const geometries=new Set(),materials=new Set();scene.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material)materials.add(o.material)});geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());renderer.dispose();renderer.domElement.remove();status.remove();dialog.remove();labels.forEach(l=>l.remove())}
 return {frame,dispose,customize,focus:host.focus};
}
